  python3 -I pdfpage.py render <file.pdf> <out.png> [--page 1] [--dpi 200] [--rot 0|90|180|270] [--deskew]
  python3 -I pdfpage.py crop <in.png> <out.png> x0 y0 x1 y1 [--zoom 2]   # toạ độ pixel; zoom phóng ảnh cắt
